    32	          const instructionParts: string[] = [];
    33	          const responsesInput: CodexResponsesInputType[] = [];
    34	
    35	          for (const message of input.messages) {
    36	            if (message.role === "system") {
    37	              if (message.content.length > 0) {
    38	                instructionParts.push(message.content);
    39	              }
    40	              continue;
    41	            }
    42	
